89	// TestSubmitReceiptRejectsInvalidUTF8Reason 覆盖各类坏字节拒绝原因：指定
90	// 接收方以正确摘要登记、其他业务条件均满足时，一律 ErrInvalidArgument 与
91	// 空回执确认；交换保持提交前状态——待回执、无回执原因与登记时间、原包与
92	// 摘要原样、不新增回执审计，关闭重开后仍然如此；此前失败不构成已拒绝，
93	// 随后换用合法原因仍能正常登记这份回执。
94	func TestSubmitReceiptRejectsInvalidUTF8Reason(t *testing.T) {
95		for _, tc := range invalidRejectionReasons {
96			t.Run(tc.label, func(t *testing.T) {
97				dir := t.TempDir()
98				clk := &fakeClock{t: time.Date(2026, 6, 4, 9, 0, 0, 0, time.UTC)}
99				open := func() *Store {
100					s, err := Open(dir, WithClock(func() time.Time { return clk.t }))
101					if err != nil {
102						t.Fatalf("open: %v", err)
103					}
104					return s
105				}
106	
107				s := open()
108				f := setupReceiptUTF8(t, s, clk)
109				x, err := s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID, []ID{f.rid}, "req-rcpt-utf8")
110				if err != nil {
111					t.Fatal(err)
112				}
113				before := snapshotExchange(mustGetExchange(t, s, f.pid, x.ID))
114				auditBefore := mustAudit(t, s, f.pid)
115	
116				// 坏字节原因：ErrInvalidArgument，且确认必须是空值（无交换标识、
117				// 状态、结果与登记时间）。
118				conf, err := s.SubmitReceipt(rcv, x.ID, x.Digest, ReceiptRejected, tc.reason)
119				if !errors.Is(err, ErrInvalidArgument) {
120					t.Fatalf("SubmitReceipt(%q) err = %v, want ErrInvalidArgument", tc.reason, err)
121				}
122				if conf != (ReceiptConfirmation{}) {
123					t.Fatalf("rejected receipt returned non-empty confirmation: %+v", conf)
124				}
125	
126				// 同样的坏字节原因再交一次，仍是参数错误，而不是“原因不同”的冲突。
127				if _, err := s.SubmitReceipt(rcv, x.ID, x.Digest, ReceiptRejected, tc.reason); !errors.Is(err, ErrInvalidArgument) {
128					t.Fatalf("repeat invalid-utf8 reason err = %v, want ErrInvalidArgument", err)
129				}
130	
131				// 当次内部视图：交换保持提交前状态——待回执、没有回执、原包与摘要
132				// 原样，审计不新增。
133				assertExchangeMatches(t, mustGetExchange(t, s, f.pid, x.ID), before, "exchange after rejected receipt")
134				if c := receiptAuditCount(t, s, f.pid); c != 0 {
135					t.Fatalf("rejected receipt left %d receipt audit events", c)
136				}
137				if audit, err := s.AuditEvents(doc, f.pid); err != nil || !reflect.DeepEqual(audit, auditBefore) {
138					t.Fatalf("audit changed after rejected receipt: %v %+v", err, audit)
139				}
140				if d, err := s.FetchPackage(rcv, x.ID); err != nil || d.Status != ExchangePending || d.Digest != x.Digest {
141					t.Fatalf("delivery changed after rejected receipt: %+v err=%v", d, err)
142				}
143	
144				// 坏字节没有落盘：关闭重开后仍是同一份待回执交换，审计不变。
145				s = reopenStore(t, s, dir, clk)
146				assertExchangeMatches(t, mustGetExchange(t, s, f.pid, x.ID), before, "exchange after reopen")
147				if audit, err := s.AuditEvents(doc, f.pid); err != nil || !reflect.DeepEqual(audit, auditBefore) {
148					t.Fatalf("audit changed after reopen: %v", err)
149				}
150	
151				// 此前失败不是已拒绝：换用合法原因仍能完成这份尚未登记的回执。
152				clk.t = clk.t.Add(time.Hour)
153				registeredAt := clk.t
154				legalReason := "换用合法原因后的拒绝说明"
155				conf2, err := s.SubmitReceipt(rcv, x.ID, x.Digest, ReceiptRejected, legalReason)
156				if err != nil {
157					t.Fatalf("legal receipt after rejected attempt: %v", err)
158				}
159				if conf2.ExchangeID != x.ID || conf2.Status != ExchangeRejected ||
160					conf2.Outcome != ReceiptRejected || !conf2.RegisteredAt.Equal(registeredAt) {
161					t.Fatalf("unexpected confirmation after legal reason: %+v", conf2)
162				}
163				got := mustGetExchange(t, s, f.pid, x.ID)
164				if got.Status != ExchangeRejected || got.Receipt == nil ||
165					got.Receipt.Outcome != ReceiptRejected || got.Receipt.Reason != legalReason ||
166					!got.Receipt.RegisteredAt.Equal(registeredAt) {
167					t.Fatalf("legal receipt not stored as expected: %+v", got.Receipt)
168				}
169				// 失败尝试不产生审计：整份交换只有成功登记这一条回执事件。
170				events := mustAudit(t, s, f.pid)
171				var rcpt []AuditEvent
172				for _, ev := range events {
173					if ev.Action == ActionReceipted && ev.ObjectID == x.ID {
174						rcpt = append(rcpt, ev)
175					}
176				}
177				if len(rcpt) != 1 || !rcpt[0].OccurredAt.Equal(registeredAt) || rcpt[0].ActorID != rcv.ID {
178					t.Fatalf("receipt audit events = %+v, want one at %v", rcpt, registeredAt)
179				}
180				_ = s.Close()
181			})
182		}
183	
184		// 空串与全空白原因继续按既有规则拒绝（与是否含坏字节无关）。
185		s, clk := newTestStore(t)
186		f := setupReceiptUTF8(t, s, clk)
187		x, err := s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID, []ID{f.rid}, "req-rcpt-blank")
188		if err != nil {
189			t.Fatal(err)
190		}
191		for _, blank := range []string{"", " ", "\n\t\r ", "　"} {
192			if _, err := s.SubmitReceipt(rcv, x.ID, x.Digest, ReceiptRejected, blank); !errors.Is(err, ErrInvalidArgument) {
193				t.Fatalf("blank rejection reason %q err = %v, want ErrInvalidArgument", blank, err)
194			}
195		}
196		got := mustGetExchange(t, s, f.pid, x.ID)
197		if got.Status != ExchangePending || got.Receipt != nil {
198			t.Fatalf("blank reasons left a receipt: %+v", got)
199		}
200	}
201	
202	// TestSubmitReceiptValidUTF8ReasonPreservedRoundTrip 覆盖合法拒绝原因：原样
203	// 保存与比较，不去首尾空白、不改写字符形态；内部使用者当次查看与关闭重开
204	// 后的查看得到相同原因；相同结果与原样原因重交返回首次确认及首次登记时间、
205	// 不新增审计；换成另一份合法原因返回 ErrConflict。
206	func TestSubmitReceiptValidUTF8ReasonPreservedRoundTrip(t *testing.T) {
207		for _, tc := range validRejectionReasons {
208			t.Run(tc.label, func(t *testing.T) {
209				dir := t.TempDir()
210				clk := &fakeClock{t: time.Date(2026, 6, 5, 9, 0, 0, 0, time.UTC)}
211				open := func() *Store {
212					s, err := Open(dir, WithClock(func() time.Time { return clk.t }))
213					if err != nil {
214						t.Fatalf("open: %v", err)
215					}
216					return s
217				}
218	
219				s := open()
220				f := setupReceiptUTF8(t, s, clk)
221				x, err := s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID, []ID{f.rid}, "req-rcpt-valid")
222				if err != nil {
223					t.Fatal(err)
224				}
225	
226				conf, err := s.SubmitReceipt(rcv, x.ID, x.Digest, ReceiptRejected, tc.reason)
227				if err != nil {
228					t.Fatalf("SubmitReceipt(%q): %v", tc.reason, err)
229				}
230				if conf.Status != ExchangeRejected || conf.Outcome != ReceiptRejected {
231					t.Fatalf("unexpected confirmation: %+v", conf)
232				}
233	
234				// 当次内部查看：原因逐字保留。
235				got := mustGetExchange(t, s, f.pid, x.ID)
236				if got.Receipt == nil || got.Receipt.Reason != tc.reason ||
237					!got.Receipt.RegisteredAt.Equal(conf.RegisteredAt) {
238					t.Fatalf("returned/stored reason mismatch: %+v", got.Receipt)
239				}
240	
241				// 相同结果与原样原因重交：首次确认与首次登记时间，不新增审计。
242				clk.t = clk.t.Add(2 * time.Hour)
243				again, err := s.SubmitReceipt(rcv, x.ID, x.Digest, ReceiptRejected, tc.reason)
244				if err != nil {
245					t.Fatalf("identical resubmit: %v", err)
246				}
247				if again.ExchangeID != conf.ExchangeID || again.Status != conf.Status ||
248					again.Outcome != conf.Outcome || !again.RegisteredAt.Equal(conf.RegisteredAt) {
249					t.Fatalf("resubmit changed confirmation:\n got=%+v\nwant=%+v (resubmit time must not be used)",
250						again, conf)
251				}
252				if c := receiptAuditCount(t, s, f.pid); c != 1 {
253					t.Fatalf("identical resubmit changed receipt audit count: %d", c)
254				}
255	
256				// 换成另一份合法原因：ErrConflict，不改写已保存原因或登记时间。
257				otherReason := "另一段完全不同但合法的拒绝原因"
258				if _, err := s.SubmitReceipt(rcv, x.ID, x.Digest, ReceiptRejected, otherReason); !errors.Is(err, ErrConflict) {
259					t.Fatalf("different-reason resubmit err = %v, want ErrConflict", err)
260				}
261				got = mustGetExchange(t, s, f.pid, x.ID)
262				if got.Receipt.Reason != tc.reason || !got.Receipt.RegisteredAt.Equal(conf.RegisteredAt) {
263					t.Fatalf("conflicting resubmit rewrote receipt: %+v", got.Receipt)
264				}
265				if c := receiptAuditCount(t, s, f.pid); c != 1 {
266					t.Fatalf("conflicting resubmit changed receipt audit count: %d", c)
267				}
268	
269				// 关闭重开：内部查看得到逐字相同原因与首次登记时间；原样原因重交
270				// 仍返回同一份确认。
271				s = reopenStore(t, s, dir, clk)
272				t.Cleanup(func() { _ = s.Close() })
273				got = mustGetExchange(t, s, f.pid, x.ID)
274				if got.Status != ExchangeRejected || got.Receipt == nil ||
275					got.Receipt.Outcome != ReceiptRejected || got.Receipt.Reason != tc.reason ||
276					!got.Receipt.RegisteredAt.Equal(conf.RegisteredAt) {
277					t.Fatalf("reason changed across reopen:\n got=%+v\nwant reason %q at %v",
278						got.Receipt, tc.reason, conf.RegisteredAt)
279				}
280				again2, err := s.SubmitReceipt(rcv, x.ID, x.Digest, ReceiptRejected, tc.reason)
281				if err != nil {
282					t.Fatalf("identical resubmit after reopen: %v", err)
283				}
284				if again2.ExchangeID != conf.ExchangeID || !again2.RegisteredAt.Equal(conf.RegisteredAt) {
285					t.Fatalf("resubmit after reopen changed confirmation: got %+v, want %+v", again2, conf)
286				}
287				if c := receiptAuditCount(t, s, f.pid); c != 1 {
288					t.Fatalf("resubmit after reopen changed receipt audit count: %d", c)
289				}
290			})
291		}
292	}
